var kthFactor = function(n, k) {
    let count = 0; // how many factors we have found so far
    for (let i = 1; i <= n; i++) {
        if (n % i === 0) {
            // i divides n evenly — it is a factor
            count++;
            if (count === k) {
                return i; // found the k-th factor
            }
        }
    }
    return -1; // fewer than k factors exist
};
